#include <iostream>
#include <string>
#include <cctype>

int main() {
    std::string input;
    if (!(std::cin >> input)) {
        return 0;
    }

    if (input.length() != 12) {
        std::cout << input << " is an invalid input\n";
        return 0;
    }

    int sum = 0;
    for (std::size_t i = 0; i < input.size(); ++i) {
        if (!std::isdigit(static_cast<unsigned char>(input[i]))) {
            std::cout << input << " is an invalid input\n";
            return 0;
        }
        int digit = input[i] - '0';
        sum += (i % 2 == 0) ? digit : 3 * digit;
    }

    int checksum = 10 - (sum % 10);
    if (checksum == 10) {
        checksum = 0;
    }

    std::cout << "The ISBN-13 number is " << input << checksum << "\n";
    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    int n;
    double r;
    if (!(std::cin >> n >> r) || n < 3) {
        return 0;
    }

    const double pi = 3.14159265358979323846;
    double angle_step = 2.0 * pi / n;

    std::cout << "The coordinates of the points on the polygon are\n";
    std::cout << std::fixed << std::setprecision(4);
    for (int i = 0; i < n; ++i) {
        double theta = i * angle_step;
        double x = r * std::cos(theta);
        double y = r * std::sin(theta);
        if (std::abs(x) < 1e-10) x = 0.0;
        if (std::abs(y) < 1e-10) y = 0.0;
        std::cout << "(" << x << ", " << y << ")\n";
    }
    return 0;
}
